import binascii
import re
from robot.api import logger


class EmilMessagesReader(object):
    """
    This class is using for reading on by one single unparsed msg from enb trace
    """
    def __init__(self,
                 emil_trace_file):
        self.emil_trace_file = emil_trace_file
        self.hex_data = self._read_bin_file()

    def unparsed_messages(self):
        """

        :return:
        """
        cli_aatracee_server_header = '636c695f616174726163655f73657276657200'
        nmap_header = '000005006e6d6170'
        msg_start_pattern = re.compile('000000[^0]{2}')
        file_end_flag = False

        while not file_end_flag:
            first_cli_aatrace_server_header = self.hex_data.find(cli_aatracee_server_header)
            if first_cli_aatrace_server_header:
                cli_aatrace_header_start_pattern = self.hex_data.find(nmap_header, first_cli_aatrace_server_header)
                cli_msg_start = msg_start_pattern.search(self.hex_data, first_cli_aatrace_server_header).start() + 2
                if cli_aatrace_header_start_pattern != -1:
                    unparsed_msg = self.hex_data[cli_msg_start:cli_aatrace_header_start_pattern]
                    self.hex_data = self.hex_data[cli_aatrace_header_start_pattern:]
                else:
                    unparsed_msg = self.hex_data[cli_msg_start:]
                    file_end_flag = True
                yield unparsed_msg
            else:
                raise HeaderCliTraceDidntFind("Cant find cli_aatrace_header in binary file, please make sure"
                                              "you are using cli_aatrace for log collecting, in other case:"
                                              " contact with package owners")

    def get_msg_number_of_occurrences(self, msg_hex_id):
        """

        :param msg_hex_id:
        :return:
        """
        if '0x' in msg_hex_id.lower():
            msg_hex_id = msg_hex_id.lower().replace('0x', '')
        msg_hex_id = '0000' + msg_hex_id.lower()
        counter = 0
        for msg in self.unparsed_messages():
            if msg_hex_id in msg:
                counter += 1
        return counter

    def _read_bin_file(self):
        """

        :return:
        """
        with open(self.emil_trace_file, 'rb') as emil_trace:
            hex_data = str((binascii.hexlify(emil_trace.read())))
        if hex_data:
            return hex_data
        else:
            logger.console("Trace Bin file is EMPTY")
            raise EmptyTraceBinFile("Trace File {} is empty, verify aatrace configuration".format(
                self.emil_trace_file
            ))


class EmptyTraceBinFile(Exception):
    """
    Exception EmptyTraceBinFile
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)


class HeaderCliTraceDidntFind(Exception):
    """
    Exception HeaderCliTraceDidntFind
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)
